import json
from typing import List, Tuple
from collections import Counter

def deep_copy(grid):
    return [list(row) for row in grid]

def solve(input_grid: List[List[int]]) -> List[List[int]]:
    h, w = len(input_grid), len(input_grid[0])

    colors = Counter()
    for row in input_grid:
        for cell in row:
            colors[cell] += 1
    background = max(colors, key=colors.get)

    center_r, center_c = None, None
    for r in range(h - 1):
        for c in range(w - 1):
            if (input_grid[r][c] == 2 and input_grid[r][c+1] == 2 and 
                input_grid[r+1][c] == 2 and input_grid[r+1][c+1] == 2):
                center_r, center_c = r, c
                break
        if center_r is not None:
            break

    if center_r is None:
        return deep_copy(input_grid)

    output = [[background for _ in range(w)] for _ in range(h)]

    corner_positions = [
        (center_r - 1, center_c - 1),  # top-left
        (center_r - 1, center_c + 2),  # top-right
        (center_r + 2, center_c - 1),  # bottom-left
        (center_r + 2, center_c + 2),  # bottom-right
    ]

    corner_colors = {}
    for r, c in corner_positions:
        corner_colors[(r,c)] = input_grid[r][c]

    perimeter_order = [
        (center_r - 1, center_c - 1),
        (center_r + 2, center_c - 1),
        (center_r + 2, center_c + 2),
        (center_r - 1, center_c + 2),
    ]

    rotated_colors = {}
    n = len(perimeter_order)
    for i, pos in enumerate(perimeter_order):
        rotated_colors[pos] = corner_colors[perimeter_order[(i+1) % n]]

    # Copy center 2x2
    output[center_r][center_c] = 2
    output[center_r][center_c+1] = 2
    output[center_r+1][center_c] = 2
    output[center_r+1][center_c+1] = 2

    # Copy rotated colors at corner positions
    for i, (r, c) in enumerate(corner_positions):
        output[r][c] = rotated_colors[(r,c)]

    # Extend rotated colors
    for r, c in corner_positions:
        color = rotated_colors.get((r,c), background)
        if color == background:
            continue

        if r < center_r:
            if c < center_c:
                # Top-left: extend UP-LEFT
                # Start from corner itself and go up-left
                curr_r, curr_c = r, c
                for k in range(max(h, w)):
                    nr, nc = curr_r - k, curr_c - k
                    if 0 <= nr < h and 0 <= nc < w:
                        output[nr][nc] = color
                    else:
                        break
            elif c > center_c:
                # Top-right: extend UP-RIGHT  
                curr_r, curr_c = r, c
                for k in range(max(h, w)):
                    nr, nc = curr_r - k, curr_c + k
                    if 0 <= nr < h and 0 <= nc < w:
                        output[nr][nc] = color
                    else:
                        break
        else:
            if c < center_c:
                # Bottom-left: extend DOWN-LEFT
                curr_r, curr_c = r, c
                for k in range(max(h, w)):
                    nr, nc = curr_r + k, curr_c - k
                    if 0 <= nr < h and 0 <= nc < w:
                        output[nr][nc] = color
                    else:
                        break
            elif c > center_c:
                # Bottom-right: extend DOWN-RIGHT
                curr_r, curr_c = r, c
                for k in range(max(h, w)):
                    nr, nc = curr_r + k, curr_c + k
                    if 0 <= nr < h and 0 <= nc < w:
                        output[nr][nc] = color
                    else:
                        break

    return output

